import * as React from "react"
import { Link, PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import SEO from "../components/seo";
import type { HeadProps } from "gatsby";
import translations from "../locales/en/index.json";
import ButtonComponent from "../components/buttons";
import ProductDisplay from "../components/productDisplay";

const userData: UserProfile = data;

const AviationPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="Tofu"
      footerLogoFill="fill-DeepSea"
      footerColorText="text-DeepSea"
      bgColorPage="Oatmeal"
      bgImage={images.bgAviation.src}
      // footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <section className={`${styles.section} mt-[300px] sm:mt-[426px]`}>
            <h1 className="head-3 sm:head-1 uppercase" dangerouslySetInnerHTML={{ __html: t("aviation_products.title") ?? "" }} />
            <h2 className="head-4 sm:head-2 uppercase mt-8" dangerouslySetInnerHTML={{ __html: t("aviation_products.subtitle") ?? "" }} />
        </section>
        <section className={styles.section}>
            <ProductDisplay translationKey="aviation_products" submenuItems={[]} />
        </section>
        <section className={`${styles.section} pb-48 pt-12 relative z-40`}>
          <div className="w-full sm:w-1/2">
              <h3 className="head-3 sm:head-1 uppercase" dangerouslySetInnerHTML={{ __html: t("aviation_products.footerTitle") ?? "" }} />
              <h4 className="body-2 sm:body-1" dangerouslySetInnerHTML={{ __html: t("aviation_products.footerText") ?? "" }} />
              <div className="mt-4 self-start">
                <ButtonComponent isSubmit={false} isDisabled={false} />
              </div>
          </div>
        </section>
    </Layout>
  )
}

export default AviationPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  section: "w-full px-5 sm:px-16 text-DeepSea",

}

export const Head = ({ location, pageContext }: HeadProps<Record<string, unknown>, { language?: string; i18n?: { originalPath?: string } }>) => (
  <SEO
    data={userData}
    title={translations.seo.retail.title}
    description={translations.seo.retail.description}
    language={pageContext.language ?? "en"}
    languages={["en"]}
    defaultLanguage="en"
    originalPath={pageContext.i18n?.originalPath ?? location.pathname}
    schemaType="ProfessionalService"
    pageSchemaType="WebPage"
    noindex
  />
);
